parameters.jsCode:
// ===== 1. CONTEXTE (messages + config) =====
// Code node, mode "Run Once for All Items"
// Rassemble ce dont les étapes suivantes ont besoin :
//   - messages : la question + les 4 derniers échanges de la session (table chat_messages) ;
//   - config   : réglages de la recherche, modifiables ici sans toucher aux autres nœuds.
const CONFIG = {
  top_k: 15,          // passages ramenés par chaque recherche (vecteurs, mots-clés)
  max_candidats: 20,  // passages envoyés au reranker après fusion
  top_n: 4,           // passages gardés pour la génération
  seuil: 0.1,         // score Cohere minimum (0 → 1) pour qu'un passage soit gardé
  rerank_model: 'rerank-v3.5',
};

const q = $('Question reçue').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.role && r.content);
const history = rows
  .slice(-8)
  .map(r => `${r.role === 'user' ? 'Utilisateur' : 'Assistant'} : ${String(r.content).slice(0, 600)}`)
  .join('\n');

return [{ json: {
  sessionId: q.sessionId,
  question: q.chatInput,
  history: history || '(aucun échange précédent)',
  config: CONFIG,
} }];

// ===== Parse routing =====
// Lit le JSON de l'étape Routing (Gemini) de façon tolérante et prépare la recherche :
//   - query_en      : requête pour la recherche vectorielle ;
//   - question_en   : question complète en anglais, pour le reranker ;
//   - mots_cles     : requête de la recherche plein texte ;
//   - filtre        : métadonnées imposées (chapitre cité explicitement), {} sinon.
// Filtre permissif : seul un in_scope explicitement false déclenche le refus.
// Nœud Google Gemini (sortie JSON) : le texte est dans content.parts[].text
const j0 = $input.first().json;
const raw = String(j0.text ?? (j0.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join(''));
const ctx = $('Contexte').first().json;

let r = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  r = JSON.parse(m ? m[0] : raw);
} catch (e) {
  r = {};
}

const standalone = String(r.standalone_fr || ctx.question).trim();
const queryEn = String(r.query_en || standalone).trim();
const motsCles = (Array.isArray(r.mots_cles_en) ? r.mots_cles_en : []).map(String).filter(Boolean).slice(0, 12);
const filtre = {};
const ch = r.filtres && r.filtres.chapitre;
if (ch !== null && ch !== undefined && /^\d{1,2}$/.test(String(ch).trim())) filtre.chapter = String(ch).trim();

return [{ json: {
  sessionId: ctx.sessionId,
  question: ctx.question,
  standalone_fr: standalone,
  in_scope: r.in_scope !== false,
  query_en: queryEn,
  question_en: String(r.question_en || queryEn).trim(),
  mots_cles: [queryEn, ...motsCles].join(' '),
  filtre,
  config: ctx.config,
} }];

// ===== Candidats (fin de l'étape SEARCH, recherche hybride) =====
// Code node, mode "Run Once for All Items"
// Fusionne deux listes de passages :
//   - « Recherche »            : les plus proches par le sens (embeddings Gemini, pgvector) ;
//   - « Recherche mots-clés »  : les meilleurs par les mots (plein texte sur le contenu augmenté).
// Fusion par Reciprocal Rank Fusion : score = Σ 1 / (60 + rang). Le filtre du routing (ex. chapitre)
// est aussi appliqué aux résultats vectoriels. Pour chaque passage :
//   - doc     : texte envoyé au reranker (contexte de l'augmentation + passage) ;
//   - passage : texte du livre seul, pour la génération.
const sel = $('Parse routing').first().json;
const K = 60;
const MAX = sel.config.max_candidats;
const filtre = sel.filtre || {};

const read = (j) => {
  const doc = j.document || j;
  return { content: String(doc.pageContent ?? doc.content ?? ''), meta: doc.metadata || {} };
};
const okFiltre = (meta) => Object.entries(filtre).every(([k, v]) => String(meta[k] ?? '') === String(v));

const pool = new Map();
const add = (items, source) => {
  let rank = 0;
  for (const item of items) {
    const { content, meta } = read(item.json || {});
    if (!content || !okFiltre(meta)) continue;
    const id = meta.chunk_id || content.slice(0, 120);
    const cur = pool.get(id) || { content, meta, rrf: 0, sources: [] };
    cur.rrf += 1 / (K + ++rank);
    cur.sources.push(source);
    pool.set(id, cur);
  }
};
add($('Recherche').all(), 'sens');
add($input.all(), 'mots-clés');

// Découpe le contenu augmenté : « [en-tête] / Context / Keywords / … / Passage: texte »
const split = (content) => {
  const i = content.indexOf('\nPassage:\n');
  if (i < 0) {
    const nl = content.indexOf('\n');
    return { header: nl > 0 ? content.slice(0, nl) : '', passage: nl > 0 ? content.slice(nl + 1) : content, contexte: '' };
  }
  const head = content.slice(0, i);
  return {
    header: head.split('\n')[0],
    contexte: (head.match(/\nContext: (.*)/) || [])[1] || '',
    passage: content.slice(i + '\nPassage:\n'.length),
  };
};

const candidates = [...pool.values()]
  .sort((a, b) => b.rrf - a.rrf)
  .slice(0, MAX)
  .map((c, i) => {
    const s = split(c.content);
    return {
      n: i,
      doc: [s.header, s.contexte, s.passage].filter(Boolean).join('\n').slice(0, 4000),
      passage: s.passage,
      book: c.meta.book ?? '',
      part: c.meta.part ?? '',
      chapter: c.meta.chapter ?? '',
      chapter_title: c.meta.chapter_title ?? '',
      section: c.meta.section ?? '',
      section_title: c.meta.section_title ?? '',
      structure: c.meta.structure ?? '',
      page: c.meta.page ?? '',
      trouve_par: c.sources.join(' + '),
      rrf: Number(c.rrf.toFixed(4)),
    };
  });

return [{ json: {
  question: sel.standalone_fr || sel.question,
  question_en: sel.question_en,
  candidates,
  documents: candidates.map(c => c.doc),
  config: sel.config,
} }];

// ===== Top N (fin de l'étape RERANKING) =====
// Code node, mode "Run Once for All Items"
// Lit les scores du reranker Cohere ({ results: [{ index, relevance_score }] }) et garde
// au plus top_n passages dont le score dépasse le seuil (config du nœud « Contexte »).
// Si Cohere n'a pas répondu (erreur, quota), on garde les top_n de la fusion RRF : le chat continue.
const prev = $('Candidats').first().json;
const { top_n, seuil } = prev.config;
const res = $input.first().json || {};

let kept, mode;
if (Array.isArray(res.results)) {
  mode = 'cohere';
  kept = res.results
    .filter(r => r.relevance_score >= seuil)
    .sort((a, b) => b.relevance_score - a.relevance_score)
    .slice(0, top_n)
    .map(r => ({ ...prev.candidates[r.index], score: Number(r.relevance_score.toFixed(3)) }));
} else {
  mode = 'secours RRF (Cohere indisponible)';
  kept = prev.candidates.slice(0, top_n);
}

// Référence de source : livre, chapitre (ou annexe), section (si le livre en a), page.
// Livre structuré par son sommaire : livre, partie › chapitre › section, page.
const short = (t) => String(t || '').replace(/\s*\(.*?\)\s*/g, ' ').trim();
const label = (c) => {
  if (c.structure === 'sommaire') {               // livre sans numéros : on cite ses titres
    const where = [c.part, c.chapter_title, /\.0$/.test(String(c.section)) ? '' : c.section_title].filter(Boolean).join(' › ');
    return [c.book && `« ${short(c.book)} »`, where, `p. ${c.page}`].filter(Boolean).join(', ');
  }
  const appendix = /^[A-Z]$/.test(String(c.chapter));
  return [
    c.book && `« ${short(c.book)} »`,
    appendix ? `annexe ${c.chapter}` : (c.chapter !== '' && c.chapter != null ? `chapitre ${c.chapter}${c.chapter_title ? ' « ' + c.chapter_title + ' »' : ''}` : ''),
    c.section && c.section !== 'p' && !appendix ? `section ${c.section} « ${c.section_title} »` : '',
    `p. ${c.page}`,
  ].filter(Boolean).join(', ');
};

const context = kept.length
  ? kept.map(c => `[Source : ${label(c)}]\n${c.passage}`).join('\n\n---\n\n')
  : 'AUCUN PASSAGE PERTINENT';

return [{ json: {
  question: prev.question,
  context,
  sources_count: kept.length,
  reranking: mode,
  scores: kept.map(c => ({ section: c.section, page: c.page, score: c.score ?? null, trouve_par: c.trouve_par })),
} }];

parameters.query:
-- CONTEXTE : 4 derniers échanges (8 messages) de la session, du plus ancien au plus récent
select role, content
from (
  select id, role, content
  from chat_messages
  where session_id = $1
  order by id desc
  limit 8
) t
order by id;

-- SEARCH (plein texte) : passages qui contiennent les mots-clés du routing, filtrés par métadonnées
select id, content, metadata, rank
from keyword_search_filtre($1, $2::int, $3::jsonb);

-- Mémoire : la question et la réponse en une seule requête
insert into chat_messages (session_id, role, content)
values ($1, 'user', $2), ($1, 'assistant', $3);
